INSERT OR IGNORE INTO products (id, data, position) VALUES ('w1', '{"id":"w1","name":"Function Liquid W1","unit":"3,79 liter","description":"Klar modelleringsvæske til akrylnegler. En salongstørrelse for det daglige arbeidet med akrylmodellering.","short":"Klar akryl liquid","tag":"AKRYL LIQUID","brand":"maiwell","group":"liquid","category":"negler","image":"assets/images/w1.webp","priceOre":null,"active":true,"safety":false,"specs":[["Type","Akryl liquid"],["Farge","Klar"],["Volum","3,79 l"]],"translations":{"en":{"name":"Function Liquid W1","unit":"3.79 litres","description":"Clear modelling liquid for acrylic nails. A salon size for everyday acrylic nail modelling.","short":"Clear acrylic liquid","tag":"ACRYLIC LIQUID","specs":[["Type","Acrylic liquid"],["Colour","Clear"],["Volume","3.79 l"]]}}}', 0);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('w2', '{"id":"w2","name":"Function Liquid W2","unit":"3,79 liter","description":"Violett modelleringsvæske til akrylnegler. Function Liquid W2 er et alternativ for deg som jobber med akrylmodellering.","short":"Violett akryl liquid","tag":"AKRYL LIQUID","brand":"maiwell","group":"liquid","category":"negler","image":"assets/images/w2.webp","priceOre":null,"active":true,"safety":false,"specs":[["Type","Akryl liquid"],["Farge","Violett"],["Volum","3,79 l"]],"translations":{"en":{"name":"Function Liquid W2","unit":"3.79 litres","description":"Violet modelling liquid for acrylic nails. Function Liquid W2 is an option for acrylic nail modelling.","short":"Violet acrylic liquid","tag":"ACRYLIC LIQUID","specs":[["Type","Acrylic liquid"],["Colour","Violet"],["Volume","3.79 l"]]}}}', 1);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('urawa', '{"id":"urawa","name":"Super UP200","unit":"Negledrill med håndstykke","description":"Elektrisk negledrill med trinnløs hastighetskontroll opptil 25 000 omdreininger per minutt. Med forover- og reversfunksjon til presist arbeid med naturlige og kunstige negler.","short":"Presisjon til arbeidsbordet","tag":"ELEKTRISK UTSTYR","brand":"URAWA","group":"utstyr","category":"elektrisk","image":"assets/images/urawa.webp","priceOre":null,"active":true,"safety":false,"specs":[["Type","Elektrisk negledrill"],["Hastighet","Opptil 25 000 o/min"],["Retning","Forover / revers"]],"translations":{"en":{"name":"Super UP200","unit":"Nail drill with handpiece","description":"Electric nail drill with variable speed control up to 25,000 revolutions per minute. Forward and reverse rotation for precise work on natural and artificial nails.","short":"Precision for your workspace","tag":"ELECTRICAL EQUIPMENT","specs":[["Type","Electric nail drill"],["Speed","Up to 25,000 rpm"],["Direction","Forward / reverse"]]}}}', 2);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('novicide', '{"id":"novicide","name":"Novicide konsentrat","unit":"2 000 ml","description":"Desinfeksjonskonsentrat til salongverktøy med ikke-porøse overflater. Følg alltid etiketten og produsentens anvisninger for blanding, kontakttid og materialer.","short":"Desinfeksjon til salongverktøy","tag":"DESINFEKSJON","brand":"NOVICIDE","group":"hygiene","category":"hygiene","image":"assets/images/novicide.webp","priceOre":null,"active":true,"safety":true,"specs":[["Type","Desinfeksjonskonsentrat"],["Volum","2 000 ml"],["Bruk","I henhold til etiketten"]],"translations":{"en":{"name":"Novicide concentrate","unit":"2,000 ml","description":"Disinfectant concentrate for salon tools with non-porous surfaces. Always follow the label and manufacturer’s instructions for dilution, contact time and suitable materials.","short":"Disinfection for salon tools","tag":"DISINFECTION","specs":[["Type","Disinfectant concentrate"],["Volume","2,000 ml"],["Use","Follow the label"]]}}}', 3);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('acetone', '{"id":"acetone","name":"Aceton","unit":"5 liter","description":"Aceton i en praktisk 5-liters kanne til salongbruk. Les alltid etiketten og produktinformasjonen før bruk.","short":"Salongstørrelse, 5 liter","tag":"RENS & FJERNING","brand":"maiwell","group":"hygiene","category":"hygiene","image":"assets/images/acetone.webp","priceOre":null,"active":true,"safety":true,"specs":[["Type","Aceton"],["Volum","5 l"],["Emballasje","Plastkanne"]],"translations":{"en":{"name":"Acetone","unit":"5 litres","description":"Acetone in a practical 5-litre container for salon use. Always read the label and product information before use.","short":"Salon size, 5 litres","tag":"CLEANSING & REMOVAL","specs":[["Type","Acetone"],["Volume","5 l"],["Packaging","Plastic container"]]}}}', 4);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('alcohol', '{"id":"alcohol","name":"Isopropanol 80 %","unit":"5 liter","description":"Klar isopropanol 80 % til forberedelse og rens i neglearbeidet. Følg produktets etikett og anvisninger før bruk.","short":"Klar isopropanol","tag":"RENS & FORBEREDELSE","brand":"maiwell","group":"hygiene","category":"hygiene","image":"assets/images/alcohol.webp","priceOre":null,"active":true,"safety":true,"specs":[["Type","Isopropanol"],["Konsentrasjon","80 %"],["Volum","5 l"]],"translations":{"en":{"name":"Isopropanol 80%","unit":"5 litres","description":"Clear isopropanol 80% for preparation and cleansing during nail work. Follow the product label and instructions before use.","short":"Clear isopropanol","tag":"CLEANSING & PREPARATION","specs":[["Type","Isopropanol"],["Concentration","80%"],["Volume","5 l"]]}}}', 5);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('buffer', '{"id":"buffer","name":"Neglebuffer 100/180","unit":"Oransje / hvit","description":"Tresidig neglebuffer med korning 100/180 og myk polstring. For utjevning og forberedelse av neglens overflate.","short":"Form, jevn ut og forbered","tag":"MANIKYRUTSTYR","brand":"maiwell","group":"utstyr","category":"manikyr","image":"assets/images/buffer.webp","priceOre":null,"active":true,"safety":false,"specs":[["Type","Tresidig buffer"],["Korning","100 / 180"],["Farge","Oransje / hvit"]],"translations":{"en":{"name":"Nail buffer 100/180","unit":"Orange / white","description":"Three-sided nail buffer with 100/180 grit and soft padding. For smoothing and preparing the nail surface.","short":"Shape, smooth and prepare","tag":"MANICURE TOOLS","specs":[["Type","Three-sided buffer"],["Grit","100 / 180"],["Colour","Orange / white"]]}}}', 6);
INSERT OR IGNORE INTO products (id, data, position) VALUES ('novicide-small', '{"id":"novicide-small","name":"Novicide konsentrat","unit":"500 ml","description":"Desinfeksjonskonsentrat til salongverktøy i en mindre flaske. Følg alltid etiketten og produsentens anvisninger for blanding, kontakttid og materialer.","short":"En mindre størrelse til salongen","tag":"DESINFEKSJON","brand":"NOVICIDE","group":"hygiene","category":"hygiene","image":"assets/images/novicide-small.webp","priceOre":null,"active":true,"safety":true,"specs":[["Type","Desinfeksjonskonsentrat"],["Volum","500 ml"],["Bruk","I henhold til etiketten"]],"translations":{"en":{"name":"Novicide concentrate","unit":"500 ml","description":"Disinfectant concentrate for salon tools in a smaller bottle. Always follow the label and manufacturer’s instructions for dilution, contact time and suitable materials.","short":"A smaller size for the salon","tag":"DISINFECTION","specs":[["Type","Disinfectant concentrate"],["Volume","500 ml"],["Use","Follow the label"]]}}}', 7);
